edits.old:
import { ensureDependenciesInstalled } from "../bootstrap.ts";

ensureDependenciesInstalled();
const { main } = await import("./cli.ts");

edits.new:
last="unknown"

case "$dirty" in
	unknown) bucket=hold-unknown ;;
	wip:*) bucket=hold-wip ;;
	*ignored:*) bucket=hold-ignored ;;
	untracked:*) bucket=hold-untracked ;;
	clean)
		if [ "$pr_open" = true ]; then bucket=hold-open-pr
		elif [ "$merged" = YES ] || [ "$pr_merged" = true ]; then bucket=safe
		else bucket=review; fi ;;

IFS=$'\t' read -r pr pr_merged pr_open < <(
	[ -n "$branch" ] && jq -r --arg branch "$branch" --arg oid "$head" --arg base "$pr_base" \
		--arg merged "$merged" --argjson allow_merge "$allow_pr_merge" '
		def pending: .state == "open" or .state == "draft";
		def matching_merge:
			$allow_merge and .state == "merged" and $oid != "" and .headRefOid == $oid
			and $base != "" and .baseRefName == $base;
		map(select(.headRefName == $branch)) as $matches
		| first($matches[] | select(pending and (.headRefOid == null or .headRefOid == $oid)))
			// first($matches[] | select(matching_merge))
			// first($matches[] | select(pending))
			// ($matches[0] // empty)
		| ["#\(.number)/\(.state)", matching_merge,
			(pending and ($merged != "YES" or .headRefOid == null or .headRefOid == $oid))]
		| @tsv
	' "$prs" 2>/dev/null
)

Use the role keys and shipped defaults loaded in step 2. After a budget is chosen, record its label in `budget` and write the mapped role values. Remove a role override to fall back to its shipped default. Scalar objects may override either or both fields. Lists replace the whole ordered list and must be nonempty; each entry is a complete model/effort object or `"inherit-parent"` or `"auto"`. Alias entries still count toward panel fan-out.

A partial override can look like this after confirming the effort is supported:

```json
{
  "version": 1,
  "budget": "medium",
  "roles": {
    "feature_refactoring": "inherit-parent",
    "judgment_and_prose": {
      "reasoning_effort": "high"
    }
  }
}
